<?php
require __DIR__.'/bootstrap.php';

$identity=udaan_player_session_identity();
$player=$identity?$store->getPlayer($identity):null;
if(!$identity||!is_array($player)||empty($player['onboarding_completed'])){header('Location: '.app_url('player'));exit;}

$date=today_key();
$state=udaan_mission_ensure_daily($store,$identity,$player,$date);
$readinessState=$store->getReadinessState($identity);
$readiness=udaan_daily_readiness_for_date($readinessState,$date);
if($readiness)$state=udaan_mission_apply_readiness($store,$identity,$readiness);
$coach=udaan_coach_generate($state,$player,$readinessState,$date);
$recommendations=(array)($coach['recommendations']??[]);
foreach($recommendations as$r)if(is_array($r))udaan_coach_record_shown_once($store,$player,$r);
$summary=(array)($coach['weekly_summary']??[]);
$arenas=udaan_player_arenas();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Coach · Udaan</title><?=common_assets_head()?><style>
.c-wrap{max-width:1120px;margin:0 auto;padding:24px 20px 72px}.c-head{display:flex;justify-content:space-between;align-items:center;gap:16px}.c-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.hero{display:grid;grid-template-columns:1.25fr .75fr;gap:20px;margin-top:30px}.panel{background:var(--panel,#fff);border:1px solid rgba(90,80,60,.14);border-radius:28px;padding:26px}.hero h1{font-size:clamp(42px,6vw,72px);line-height:.96;margin:6px 0 16px}.summary{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.metric strong{display:block;font-size:38px}.metric small{opacity:.66}.rec-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:20px}.rec{display:flex;flex-direction:column;min-height:300px}.rec h2{font-size:27px;margin:8px 0}.rec p{line-height:1.55}.tag{display:inline-flex;align-self:flex-start;border:1px solid rgba(90,80,60,.16);border-radius:999px;padding:7px 10px;font-size:11px;letter-spacing:.06em}.reason{font-family:ui-monospace,monospace;font-size:11px;opacity:.62;margin-top:auto}.evidence{margin:12px 0;padding:12px;border-radius:14px;background:rgba(90,80,60,.05);font-size:12px;line-height:1.45}.accept{margin-top:14px}.empty{opacity:.7}.explain{font-size:13px;line-height:1.55;opacity:.75}@media(max-width:860px){.hero,.rec-grid{grid-template-columns:1fr}.summary{grid-template-columns:repeat(4,1fr)}}@media(max-width:560px){.summary{grid-template-columns:1fr 1fr}.panel{padding:20px}}
